inline const size_t kTtfN = sizeof(kTtf);

inline uint16_t gidOf(uint32_t ucs) {   // 二分; 未命中返回 0 (.notdef)
    size_t lo = 0, hi = kCmapN;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (kCmap[mid].ucs < ucs) lo = mid + 1; else hi = mid;
    }
    return (lo < kCmapN && kCmap[lo].ucs == ucs) ? kCmap[lo].gid : 0;
}
inline uint16_t widthOf(uint16_t gid) { return gid < kWidthN ? kWidth[gid] : 0; }

